import sys
import re

def main():
    input_lines = sys.stdin.read().splitlines()
    # Skip the first line
    input_line = input_lines[1]
    # Split the input line based on parentheses with optional letters inside
    split_parts = re.split(r"\([a-zA-Z_]*\)", input_line)
    longest_word = 0
    for segment in split_parts:
        words = re.split(r"_+", segment)
        for word in words:
            if len(word) > longest_word:
                longest_word = len(word)
    parentheses_count = 0
    current_count = 0
    in_parentheses = False
    counted_in_parentheses = False
    for ch in input_line:
        if ch == '(':
            in_parentheses = True
        if ch == ')':
            counted_in_parentheses = False
            in_parentheses = False
        if in_parentheses and ch.isalpha():
            if counted_in_parentheses:
                continue
            parentheses_count += 1
            counted_in_parentheses = True
        if ch == '_':
            counted_in_parentheses = False
    print(f"{longest_word} {parentheses_count}")

if __name__ == "__main__":
    main()

